        BriefingTask::upsert(
            $tasks,
            uniqueBy: ['key'],
            update: ['branch_id', 'label', 'group', 'group_label', 'period', 'include_in_score', 'submission_type', 'note_type', 'is_active', 'sort_order', 'deadline_enabled', 'deadline_day', 'deadline_time'],
        );

        // Not a conflicting mass-override (docs/daily-briefing-remediation-prd.md §16.2 only asks
        // to remove one if it fights real per-task configuration): BriefingTask::booted()'s
        // `saving` hook and the 2026_07_29_000001 migration already make "every weekly point
        // deadlines Monday-week's-Sunday 23:59, every monthly point deadlines end-of-month 23:59"
        // a hard, system-wide invariant with no per-task override (see
        // tests/Feature/BriefingAutomaticDeadlineTest.php, including the admin form rendering
        // these fields read-only). upsert() bypasses Eloquent events, so this is what keeps
        // seeded rows consistent with that invariant instead of persisting the stale literal
        // `deadline_enabled => false` some rows above still carry from before the rule existed.
        BriefingTask::query()->where('period', 'weekly')->update([
            'deadline_enabled' => true,
            'deadline_day' => 7,
            'deadline_time' => '23:59:00',
        ]);
        BriefingTask::query()->where('period', 'monthly')->update([
            'deadline_enabled' => true,
            'deadline_day' => 0,
            'deadline_time' => '23:59:00',
        ]);
        BriefingTask::clearCache();
    }
